import type { SampleId } from './ids';

/** Where a sample's audio comes from: generated by a built-in generator, or embedded (stored by content hash). */
export type SampleSource =
  | { kind: 'builtin'; generator: string; version: number }
  | { kind: 'embedded'; hash: string; ext: string; originalName?: string };

/** A sample of the project: a name, where its audio comes from and the facts known about it. */
export interface SampleRef {
  id: SampleId;
  name: string;
  source: SampleSource;
  /** Facts recorded at import time (absent for generated samples). */
  durationSec?: number;
  sampleRate?: number;
  channels?: number;
}
